def longest_semi_repetitive_substring(s):
    # Create a dictionary to store the count of each digit
    count_dict = {}
    for i in range(len(s)):
        count_dict[s[i]] = count_dict.get(s[i], 0) + 1

    # Find the longest semi-repetitive substring
    max_length = 0
    max_substring = ""
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] == s[j]:
                count_dict[s[i]] -= 1
                if count_dict[s[i]] == 0:
                    max_length = max(max_length, j - i + 1)
                    max_substring = s[i:j + 1]
                    break
    return max_length, max_substring

