def maxGroups(usageLimits):
    n = len(usageLimits)
    groups = [[] for _ in range(n)]

    for i in range(n):
        groups[i].append(usageLimits[i])

    for i in range(n-1, -1, -1):
        if len(groups[i]) > len(groups[i-1]):
            groups[i].append(groups[i-1][0])
            del groups[i-1][0]

    return len(groups[0])

