def min_time(N, A, B, C):
    # Initialize the minimum time to be the maximum possible time
    min_time = float('inf')

    # Initialize the distance matrix
    distances = [[0] * (N + 1) for _ in range(N + 1)]

    # Initialize the city to city distances
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            distances[i][j] = A * distances[i - 1][j] + B * distances[i - 1][j - 1] + C

    # Initialize the city to city train distances
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            distances[i][j] += B * distances[i - 1][j] + C

    # Initialize the city to city car distances
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            distances[i][j] += A * distances[i - 1][j]

    # Find the minimum time
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if distances[i][j] < min_time:
                min_time = distances[i][j]

    return min_time

