def toroidal_grid(H, W, N):
    grid = [["#" for _ in range(W)] for _ in range(H)]

    for _ in range(N):
        for i in range(H):
            for j in range(W):
                if grid[i][j] == "#":
                    grid[i][j] = " "
                    rotate_grid(grid, i, j, H, W)
                    grid[i][j] = "#"

    return grid

def rotate_grid(grid, i, j, H, W):
    if i == H - 1 and j == W - 1:
        return

    if i == 0 and j == 0:
        return

    if i == 0:
        grid[i][j] = grid[i][j - 1]
        grid[i][j - 1] = "#"
        rotate_grid(grid, i - 1, j, H, W)

    if j == 0:
        grid[i][j] = grid[i - 1][j]
        grid[i - 1][j] = "#"
        rotate_grid(grid, i, j - 1, H, W)

    if i == H - 1 and j == W - 1:
        return

    if i == H - 1:
        grid[i][j] = grid[i - 1][j]
        grid[i - 1][j] = "#"
        rotate_grid(grid, i, j - 1, H, W)

    if j == W - 1:
        grid[i][j] = grid[i][j - 1]
        grid[i][j - 1] = "#"
        rotate_grid(grid, i, j, H, W)

