def generate_arithmetic_sequence(A, B, D):
    if A > B or D > B:
        return "Invalid input"
    if A == B:
        return "No arithmetic sequence exists with first term " + str(A) + " and last term " + str(B) + " with common difference " + str(D)
    if D == 0:
        return "No arithmetic sequence exists with first term " + str(A) + " and last term " + str(B) + " with common difference " + str(D)
    if D < 0:
        return "Invalid input"
    sequence = [A]
