    for perm in permutations(P):
        # Create a good index sequence
        i_1, i_2, i_3, i_4 = perm

        # Check if the sequence is a good index sequence
        if 1 <= i_1 < i_2 < i_3 < i_4 <= N:
            # Check if the subsequence (P_i_1, P_i_2, P_i_3, P_i_4) can be obtained by rearranging some consecutive K integers
            if (P[i_1], P[i_2], P[i_3], P[i_4]) == (P[i_1 + 1], P[i_1 + 2], P[i_1 + 3], P[i_1 + 4]):
